class Solution {
public:
    int minimumValueSum(vector<int>& nums, vector<int>& andValues) {
        int n = nums.size(), m = andValues.size();
        map<tuple<int, int, int>, int> memo;

        auto dfs = [&](auto& self, int i, int j, int cur_and) -> int {
            if (i == n && j == m) return 0;
            if (i == n || j == m) return 1e9;

            cur_and = (cur_and == -1) ? nums[i] : (cur_and & nums[i]);
            if ((cur_and & andValues[j]) != andValues[j]) return 1e9;

            auto key = make_tuple(i, j, cur_and);
            if (memo.count(key)) return memo[key];

            int ans = self(self, i + 1, j, cur_and);
            if (cur_and == andValues[j]) {
                ans = min(ans, nums[i] + self(self, i + 1, j + 1, -1));
            }

            return memo[key] = ans;
        };

        int res = dfs(dfs, 0, 0, -1);
        return res >= 1e9 ? -1 : res;
    }
};

class Solution {
    private static final int INF = 1_000_000_000;

    public int minimumValueSum(int[] nums, int[] andValues) {
        Map<String, Integer> memo = new HashMap<>();
        int res = dfs(0, 0, -1, nums, andValues, memo);
        return res >= INF ? -1 : res;
    }

    private int dfs(int i, int j, int curAnd, int[] nums, int[] andValues, Map<String, Integer> memo) {
        int n = nums.length, m = andValues.length;
        if (i == n && j == m) return 0;
        if (i == n || j == m) return INF;

        curAnd = (curAnd == -1) ? nums[i] : (curAnd & nums[i]);
        if ((curAnd & andValues[j]) != andValues[j]) return INF;

        String key = i + "," + j + "," + curAnd;
        if (memo.containsKey(key)) return memo.get(key);

        int ans = dfs(i + 1, j, curAnd, nums, andValues, memo);
        if (curAnd == andValues[j]) {
            ans = Math.min(ans, nums[i] + dfs(i + 1, j + 1, -1, nums, andValues, memo));
        }

        memo.put(key, ans);
        return ans;
    }
}

var minimumValueSum = function(nums, andValues) {
    const n = nums.length, m = andValues.length;
    const memo = new Map();
    const INF = 1000000000;

    function dfs(i, j, curAnd) {
        if (i === n && j === m) return 0;
        if (i === n || j === m) return INF;

        curAnd = (curAnd === -1) ? nums[i] : (curAnd & nums[i]);
        if ((curAnd & andValues[j]) !== andValues[j]) return INF;

        const key = `${i},${j},${curAnd}`;
        if (memo.has(key)) return memo.get(key);

        let ans = dfs(i + 1, j, curAnd);
        if (curAnd === andValues[j]) {
            ans = Math.min(ans, nums[i] + dfs(i + 1, j + 1, -1));
        }

        memo.set(key, ans);
        return ans;
    }

    const res = dfs(0, 0, -1);
    return res >= INF ? -1 : res;
};
